using System.Net;
using System.Net.Http.Json;
using CondoManager.Application;
using CondoManager.Domain;
using CondoManager.Infrastructure;
using Microsoft.EntityFrameworkCore;
using Npgsql;
namespace CondoManager.IntegrationTests;
[Collection("PostgreSQL")]
public class VotingTests
{
 private sealed record Context(Guid? TenantId):ICurrentTenant{public Guid? UserId=>TenantId;public StudioRole? Role=>StudioRole.StudioAdmin;}
 private static AppDbContext Db(Guid? tenant=null)=>new(new DbContextOptionsBuilder<AppDbContext>().UseNpgsql(Environment.GetEnvironmentVariable("CONDOMANAGER_TEST_POSTGRES")).Options,new Context(tenant));
 private static async Task<T> Send<T>(HttpClient c,string path,object body,string method="POST"){using var r=await c.SendAsync(new(new HttpMethod(method),path){Content=JsonContent.Create(body,options:SecurityTestHost.Json)});Assert.True(r.IsSuccessStatusCode,$"{path}: {r.StatusCode}: {await r.Content.ReadAsStringAsync()}");return(await r.Content.ReadFromJsonAsync<T>(SecurityTestHost.Json))!;}
 private static async Task<HttpStatusCode> Status(HttpClient c,string path,object body){using var r=await c.PostAsJsonAsync(path,body,SecurityTestHost.Json);return r.StatusCode;}
 private static async Task ExecuteDdl(AppDbContext db,string sql){await using var connection=new NpgsqlConnection(db.Database.GetConnectionString());await connection.OpenAsync();await using var command=new NpgsqlCommand(sql,connection);await command.ExecuteNonQueryAsync();}
 private static readonly ElectorateOptions Options=new("Synthetic manual verification of subject, notices, titles and proxy legal limits",[]);
 internal sealed class Fixture(MeetingTests.Fixture f,Guid constitutive,Guid deliberative):IAsyncDisposable
 {
  public MeetingTests.Fixture F=>f;public HttpClient C=>f.C;public string Path=>f.Path;public int V=>f.V;public Guid Const=>constitutive;public Guid Rule=deliberative;public Guid Session=>f.D.Meeting.Sessions.First().Id;public DecisionsDto D=new(f.V,[],[],[],[],[],null);
  public async Task Act(string suffix,object input){D=await Send<DecisionsDto>(C,Path+suffix,input);f.D=(await C.GetFromJsonAsync<MeetingDetails>(Path,SecurityTestHost.Json))!;}
  public async Task Check()=>await Act("/quorum",new QuorumInput(V,Session,Const,Options));
  public OpenVoteInput Open(Guid? agenda=null)=>new(V,Guid.NewGuid(),Session,agenda??f.D.Meeting.Agenda[0].Id,Rule,D.Quorums.Last().Id,Options);
  public async Task VoteAll(BallotChoice choice=BallotChoice.InFavor){var v=D.Votes.Last();foreach(var r in v.Evidence.Electorate.Rights.Where(r=>r.IsPresent))await Act($"/votes/{v.Id}/ballots",new BallotInput(V,r.HeadKey,choice));}
  public async Task<ResolutionDto> FinalizeVote(){var vote=D.Votes.Last();await Act($"/votes/{vote.Id}/close",new VoteCommand(V));await Act("/resolutions",new ResolutionInput(V,Guid.NewGuid(),vote.Id,"Synthetic resolution","Synthetic approved text"));return D.Resolutions.Last();}
  public async Task ExitAll(){foreach(var a in f.D.Attendances.Where(a=>a.CheckOutAt==null).ToArray())await f.Change($"/attendances/{a.Id}/exit",new AttendanceExit(V,DateTimeOffset.UtcNow));}
  public async ValueTask DisposeAsync()=>await f.DisposeAsync();
 }
 private static async Task<VotingRuleDto> Rule(MeetingTests.Fixture f,string code,VotingPurpose purpose,AgendaCategory? category=null){var criteria=new VotingCriteria(purpose,MeetingCall.First,category,new(1,2,purpose==VotingPurpose.Constitutive?VotingDenominator.Eligible:VotingDenominator.Present,ThresholdComparison.GreaterThan),new(purpose==VotingPurpose.Constitutive?2:1,purpose==VotingPurpose.Constitutive?3:2,VotingDenominator.Building,ThresholdComparison.AtLeast),"Synthetic configurable reference","Synthetic manually verified scope");var r=await Send<VotingRuleDto>(f.C,f.Base+"/voting-rules",new VotingRuleInput(code,"Synthetic criterion",criteria,new(2026,1,1),null));return await Send<VotingRuleDto>(f.C,f.Base+$"/voting-rules/{r.Id}/activate",new RuleReviewInput("Synthetic explicit review, no certification"));}
 internal static async Task<Fixture> Setup(bool allPresent=true,MeetingReference? target=null,bool historical=false,bool draftTarget=false,bool noticesSent=true){var f=await MeetingTests.Setup();
 if(target==MeetingReference.Budget){var budget=historical?(await f.C.GetFromJsonAsync<BudgetDto[]>(f.Data.Base.Base,SecurityTestHost.Json))!.Single(b=>b.Id==f.Data.Budget):await Send<BudgetDto>(f.C,f.Data.Base.Base,f.Data.Base.Input(106733.48m,f.Data.Budget));if(!historical&&!draftTarget)await Send<BudgetDto>(f.C,f.Data.Base.Base+$"/{budget.Id}/propose",new{});await f.Change("/agenda",new AgendaInput(f.V,null,"Synthetic budget approval",null,AgendaCategory.BudgetApproval,MeetingReference.Budget,budget.Id));}
 if(target==MeetingReference.FinalStatement){var path=$"/api/final-statements/condominiums/{f.Data.Base.Condo}";await Send<OpeningDto>(f.C,path+$"/periods/{f.Data.Base.Period}/opening",new OpeningInput(Guid.NewGuid(),OpeningMode.VerifiedZero,"Synthetic verified initial zero"));var input=new FinalInput(f.Data.Base.Period,"Synthetic actual version",Guid.NewGuid(),false,new(2026,1,1),f.Data.Units.Select((u,n)=>new DebtorSelection(u,f.Data.People[n],1)).ToArray());var statement=await Send<FinalDto>(f.C,path,input);await Send<FinalDto>(f.C,path+$"/{statement.Id}/propose",new{});await f.Change("/agenda",new AgendaInput(f.V,null,"Synthetic final approval",null,AgendaCategory.FinalStatementApproval,MeetingReference.FinalStatement,statement.Id));}
 await f.Convene();if(noticesSent)foreach(var n in f.D.Notices.ToArray()){await f.Change($"/notices/{n.Id}/status",new NoticeTransition(f.V,NoticeStatus.Ready,DateTimeOffset.UtcNow,null,null));await f.Change($"/notices/{n.Id}/status",new NoticeTransition(f.V,NoticeStatus.Sent,DateTimeOffset.UtcNow,"Synthetic declaration",null));}var session=f.D.Meeting.Sessions.First();await f.Change($"/sessions/{session.Id}",new SessionTransition(f.V,SessionStatus.InProgress));if(allPresent)for(int n=0;n<f.Data.People.Length;n++)await f.Change("/attendances",new AttendanceInput(f.V,session.Id,f.Data.People[n],AttendanceType.InPerson,null,[f.Data.Units[n]],DateTimeOffset.UtcNow,null));var c=await Rule(f,"C",VotingPurpose.Constitutive);var d=await Rule(f,"D",VotingPurpose.Deliberative);return new(f,c.Id,d.Id);}
 [PostgresFact]public async Task VoteResolutionAndCompletionAreImmutableIdempotentAndBalanced(){await using var f=await Setup();await f.Check();Assert.Equal(QuorumOutcome.Satisfied,f.D.Quorums.Last().Outcome);var open=f.Open();await f.Act("/votes",open);var vote=f.D.Votes.Single();await f.Act("/votes",open);Assert.Single(f.D.Votes);await f.VoteAll();var res=await f.FinalizeVote();Assert.Equal(VoteOutcome.Approved,res.Outcome);var duplicate=new ResolutionInput(f.V,Guid.NewGuid(),vote.Id,"Synthetic resolution","Synthetic approved text",res.Id,"Synthetic text correction");await f.Act("/resolutions",duplicate);await f.Act("/resolutions",duplicate);Assert.Equal(2,f.D.Resolutions.Count);Assert.Equal(res.Id,f.D.Resolutions.Last().PreviousResolutionId);
  var review=(await f.C.GetFromJsonAsync<CompletionReview>(f.Path+$"/completion-review?session={f.Session}",SecurityTestHost.Json))!;Assert.False(review.CanComplete);await f.ExitAll();review=(await f.C.GetFromJsonAsync<CompletionReview>(f.Path+$"/completion-review?session={f.Session}",SecurityTestHost.Json))!;Assert.True(review.CanComplete,string.Join(" ",review.Checks));var input=new CompleteMeetingInput(f.V,Guid.NewGuid(),f.Session,review.Fingerprint,"Synthetic completion");await f.Act("/complete",input);var completion=f.D.Completion!.Id;await f.Act("/complete",input);Assert.Equal(completion,f.D.Completion!.Id);Assert.Equal(MeetingStatus.Completed,f.F.D.Meeting.Status);using var viewer=f.F.Data.Base.Host.Browser();await SecurityTestHost.Login(viewer,await f.F.Data.Base.Host.Account(f.F.Data.Base.Tenant,StudioRole.Viewer),f.F.Data.Base.Tenant);var redacted=(await viewer.GetFromJsonAsync<DecisionsDto>(f.Path+"/decisions",SecurityTestHost.Json))!;Assert.DoesNotContain("Contact",redacted.Completion!.ContentJson);Assert.DoesNotContain("MailingAddress",redacted.Completion.ContentJson);Assert.Equal(HttpStatusCode.Forbidden,await Status(viewer,f.Path+"/complete",input));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/votes/{vote.Id}/ballots",new BallotInput(f.V,vote.Evidence.Electorate.Rights[0].HeadKey,BallotChoice.Against)));
  await using var db=Db(f.F.Data.Base.Tenant);await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"MeetingResolutions\" SET \"ResolutionText\"={"tamper"} WHERE \"Id\"={res.Id}"));await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"MeetingVotes\" SET \"ElectorateJson\"='{{}}'::jsonb WHERE \"Id\"={vote.Id}"));
 }
 [PostgresFact]public async Task BallotsAreUniqueVersionedAndCannotChangeAfterClosing(){await using var f=await Setup();await f.Check();await f.Act("/votes",f.Open());var v=f.D.Votes.Single();await f.ExitAll();Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/sessions/{f.Session}",new SessionTransition(f.V,SessionStatus.Ended)));var head=v.Evidence.Electorate.Rights.First();await f.Act($"/votes/{v.Id}/ballots",new BallotInput(f.V,head.HeadKey,BallotChoice.Against));var ballot=f.D.Votes.Single().Ballots.Single();Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/votes/{v.Id}/ballots",new BallotInput(f.V,head.HeadKey,BallotChoice.InFavor)));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/votes/{v.Id}/ballots",new BallotInput(f.V,"FOREIGN",BallotChoice.InFavor)));var command=new BallotInput(f.V,head.HeadKey,BallotChoice.InFavor,ballot.Id,ballot.Revision);var statuses=await Task.WhenAll(Status(f.C,f.Path+$"/votes/{v.Id}/ballots",command),Status(f.C,f.Path+$"/votes/{v.Id}/ballots",command));Assert.Contains(HttpStatusCode.OK,statuses);Assert.Contains(HttpStatusCode.Conflict,statuses);f.F.D=(await f.C.GetFromJsonAsync<MeetingDetails>(f.Path,SecurityTestHost.Json))!;await f.Act($"/votes/{v.Id}/close",new VoteCommand(f.V));Assert.Equal(1,f.D.Votes.Single().Evaluation.Totals.InFavor);Assert.Equal(2,f.D.Votes.Single().Evaluation.Totals.NonVoting);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/votes/{v.Id}/ballots",command with{ExpectedVersion=f.V}));await using var db=Db(f.F.Data.Base.Tenant);Assert.Equal(2,await db.MeetingBallotRevisions.CountAsync(b=>b.BallotId==ballot.Id));}
 [PostgresFact]public async Task ElectorateFreezesExitsAndDoesNotAdmitLateArrivals(){await using var f=await Setup();var leave=f.F.D.Attendances.Single(a=>a.PersonId==f.F.Data.People[2]);await f.F.Change($"/attendances/{leave.Id}/exit",new AttendanceExit(f.V,DateTimeOffset.UtcNow));await f.Check();Assert.Equal(QuorumOutcome.Satisfied,f.D.Quorums.Last().Outcome);await f.Act("/votes",f.Open());var vote=f.D.Votes.Single();var absent=vote.Evidence.Electorate.Rights.Single(r=>r.PrincipalId==f.F.Data.People[2]);Assert.False(absent.IsPresent);await f.F.Change("/attendances",new AttendanceInput(f.V,f.Session,f.F.Data.People[2],AttendanceType.InPerson,null,[f.F.Data.Units[2]],DateTimeOffset.UtcNow,null));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/votes/{vote.Id}/ballots",new BallotInput(f.V,absent.HeadKey,BallotChoice.InFavor)));var still=(await f.C.GetFromJsonAsync<DecisionsDto>(f.Path+"/decisions",SecurityTestHost.Json))!.Votes.Single();Assert.Equal(vote.SourceFingerprint,still.SourceFingerprint);Assert.False(still.Evidence.Electorate.Rights.Single(r=>r.HeadKey==absent.HeadKey).IsPresent);}
 [PostgresFact]public async Task UnsatisfiedOrUndeterminedQuorumCannotOpenVote(){await using var f=await Setup(false);await f.Check();Assert.Equal(QuorumOutcome.NotSatisfied,f.D.Quorums.Last().Outcome);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+"/votes",f.Open()));var exclude=new QuorumInput(f.V,f.Session,f.Const,new("Synthetic reviewed exclusion",[new(f.F.Data.Units[0],"Synthetic exclusion")]));await f.Act("/quorum",exclude);Assert.Equal(QuorumOutcome.NotSatisfied,f.D.Quorums.Last().Outcome);await f.F.Change("/attendances",new AttendanceInput(f.V,f.Session,f.F.Data.People[0],AttendanceType.InPerson,null,[f.F.Data.Units[0]],DateTimeOffset.UtcNow,null));await f.Check();Assert.Equal(QuorumOutcome.NotSatisfied,f.D.Quorums.Last().Outcome);}
 [PostgresFact]public async Task ApplyExactBudgetVersionExplicitlyWithoutDuplicatingAccounting(){await using var f=await Setup(target:MeetingReference.Budget);await f.Check();await f.Act("/votes",f.Open());var target=f.D.Votes.Last().Evidence.Target!;Assert.Equal(2,target.Version);await f.VoteAll();var resolution=await f.FinalizeVote();await using var db=Db(f.F.Data.Base.Tenant);var before=await db.JournalEntries.CountAsync();var input=new ApplyResolutionInput(f.V,Guid.NewGuid());await f.Act($"/resolutions/{resolution.Id}/apply",input);await f.Act($"/resolutions/{resolution.Id}/apply",input);Assert.Single(f.D.Applications);db.ChangeTracker.Clear();var budget=await db.Budgets.SingleAsync(b=>b.Id==target.Id);Assert.Equal(BudgetStatus.Approved,budget.Status);Assert.Equal(106733.48m,await db.BudgetLines.Where(l=>l.BudgetId==budget.Id).SumAsync(l=>l.Amount));Assert.Contains(resolution.Id.ToString(),budget.DecisionReference);Assert.Equal(before,await db.JournalEntries.CountAsync());Assert.Empty(await db.InstallmentPlans.Where(p=>p.BudgetId==budget.Id).ToArrayAsync());}
 [PostgresFact]public async Task AlreadyApprovedBudgetGetsHistoricalLinkWithoutChangingDate(){await using var f=await Setup(target:MeetingReference.Budget,historical:true);await f.Check();await f.Act("/votes",f.Open());await f.VoteAll();var r=await f.FinalizeVote();await using var db=Db(f.F.Data.Base.Tenant);var before=await db.Budgets.SingleAsync(b=>b.Id==f.F.Data.Budget);var date=before.ApprovedAt;var reference=before.DecisionReference;Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/resolutions/{r.Id}/apply",new ApplyResolutionInput(f.V,Guid.NewGuid())));await f.Act($"/resolutions/{r.Id}/apply",new ApplyResolutionInput(f.V,Guid.NewGuid(),true));db.ChangeTracker.Clear();var after=await db.Budgets.SingleAsync(b=>b.Id==f.F.Data.Budget);Assert.Equal(date,after.ApprovedAt);Assert.Equal(reference,after.DecisionReference);Assert.True(f.D.Applications.Single().HistoricalOnly);}
 [PostgresFact]public async Task ApplyFinalStatementUsesExistingApprovalAndCreatesNoJournal(){await using var f=await Setup(target:MeetingReference.FinalStatement);await f.Check();await f.Act("/votes",f.Open());await f.VoteAll();var r=await f.FinalizeVote();await using var db=Db(f.F.Data.Base.Tenant);var before=await db.JournalEntries.CountAsync();await f.Act($"/resolutions/{r.Id}/apply",new ApplyResolutionInput(f.V,Guid.NewGuid()));var id=f.D.Applications.Single().RelatedId;Assert.Equal(FinalStatementStatus.Approved,(await db.FinalStatementRows.SingleAsync(s=>s.Id==id)).Status);Assert.Equal(before,await db.JournalEntries.CountAsync());}
 [PostgresFact]public async Task ChangedTargetVersionContentCannotBeApprovedByOldVote(){await using var f=await Setup(target:MeetingReference.Budget,draftTarget:true);await f.Check();await f.Act("/votes",f.Open());var target=f.D.Votes.Last().Evidence.Target!;await f.VoteAll();var r=await f.FinalizeVote();var b=f.F.Data.Base;await Send<BudgetDto>(f.C,b.Base+$"/{target.Id}",b.Input(120000,f.F.Data.Budget),"PUT");await Send<BudgetDto>(f.C,b.Base+$"/{target.Id}/propose",new{});Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/resolutions/{r.Id}/apply",new ApplyResolutionInput(f.V,Guid.NewGuid())));await using var db=Db(b.Tenant);Assert.Equal(BudgetStatus.Proposed,(await db.Budgets.SingleAsync(x=>x.Id==target.Id)).Status);Assert.Empty(await db.ResolutionApplications.ToArrayAsync());} [PostgresFact]public async Task RulesAreVersionedAndScopeRoleAndCsrfAreEnforced(){await using var f=await Setup();var existing=(await f.C.GetFromJsonAsync<VotingRuleDto[]>(f.F.Base+"/voting-rules",SecurityTestHost.Json))!.First();var next=await Send<VotingRuleDto>(f.C,f.F.Base+"/voting-rules",new VotingRuleInput(existing.Code,"Synthetic next",existing.Criteria,new(2026,1,1),null,existing.Id));Assert.Equal(2,next.Version);Assert.Equal(VotingRuleStatus.Draft,next.Status);await f.Check();using var viewer=f.F.Data.Base.Host.Browser();await SecurityTestHost.Login(viewer,await f.F.Data.Base.Host.Account(f.F.Data.Base.Tenant,StudioRole.Viewer),f.F.Data.Base.Tenant);Assert.Equal(HttpStatusCode.Forbidden,await Status(viewer,f.Path+"/quorum",new QuorumInput(f.V,f.Session,f.Const,Options)));using var collab=f.F.Data.Base.Host.Browser();await SecurityTestHost.Login(collab,await f.F.Data.Base.Host.Account(f.F.Data.Base.Tenant,StudioRole.Collaborator),f.F.Data.Base.Tenant);Assert.Equal(HttpStatusCode.Forbidden,await Status(collab,f.F.Base+"/voting-rules",new VotingRuleInput("NO","No",existing.Criteria,new(2026,1,1),null)));using var noCsrf=f.F.Data.Base.Host.Browser();await SecurityTestHost.Login(noCsrf,await f.F.Data.Base.Host.Account(f.F.Data.Base.Tenant),f.F.Data.Base.Tenant);noCsrf.DefaultRequestHeaders.Remove("X-CSRF-TOKEN");Assert.Equal(HttpStatusCode.BadRequest,await Status(noCsrf,f.Path+"/quorum",new QuorumInput(f.V,f.Session,f.Const,Options)));await using var other=await Setup();Assert.Equal(HttpStatusCode.NotFound,(await other.C.GetAsync(f.Path+"/decisions")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,await Status(f.C,f.Path+"/quorum",new QuorumInput(f.V,f.Session,other.Const,Options)));}
 [PostgresFact]public async Task WrittenProxyRepresentsOneHeadAndCanBeRevokedBeforeOpening(){await using var f=await Setup(false);await f.F.Change("/proxies",new ProxyInput(f.V,f.F.Data.People[0],f.F.Data.People[1],[f.F.Data.Units[0]],DateTimeOffset.UtcNow,null,"Synthetic written proxy"));var proxy=f.F.D.Proxies.Single();await f.F.Change($"/proxies/{proxy.Id}/status",new ProxyTransition(f.V,ProxyStatus.Submitted));await f.F.Change($"/proxies/{proxy.Id}/status",new ProxyTransition(f.V,ProxyStatus.Verified));await f.F.Change("/attendances",new AttendanceInput(f.V,f.Session,f.F.Data.People[1],AttendanceType.InPerson,null,[f.F.Data.Units[1]],DateTimeOffset.UtcNow,null));await f.Check();Assert.Equal(QuorumOutcome.Satisfied,f.D.Quorums.Last().Outcome);Assert.Equal(2,f.D.Quorums.Last().Evaluation.Totals.Present);Assert.Equal(800,f.D.Quorums.Last().Evaluation.Totals.PresentValue);await f.Act("/votes",f.Open());var vote=f.D.Votes.Single();foreach(var right in vote.Evidence.Electorate.Rights.Where(r=>r.IsPresent)){Assert.Equal(f.F.Data.People[1],right.ExpressedById);await f.Act($"/votes/{vote.Id}/ballots",new BallotInput(f.V,right.HeadKey,right.PrincipalId==f.F.Data.People[0]?BallotChoice.InFavor:BallotChoice.Against));}await f.Act($"/votes/{vote.Id}/close",new VoteCommand(f.V));Assert.Equal(500,f.D.Votes.Single().Evaluation.Totals.InFavorValue);Assert.Equal(300,f.D.Votes.Single().Evaluation.Totals.AgainstValue);await f.F.Change($"/proxies/{proxy.Id}/status",new ProxyTransition(f.V,ProxyStatus.Revoked));await f.Check();Assert.Equal(QuorumOutcome.NotSatisfied,f.D.Quorums.Last().Outcome);Assert.Equal(1,f.D.Quorums.Last().Evaluation.Totals.Present);Assert.Equal(2,f.D.Votes.Single().Evaluation.Totals.Present);}
 [PostgresFact]public async Task MissingNoticeDeclarationsAreUndeterminedAndCannotConstitute(){await using var f=await Setup(noticesSent:false);await f.Check();Assert.Equal(QuorumOutcome.Undetermined,f.D.Quorums.Last().Outcome);Assert.Contains(f.D.Quorums.Last().Evaluation.Anomalies,a=>a.Contains("convocazioni"));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+"/votes",f.Open()));}
 [PostgresFact]public async Task RejectedAndUndeterminedResolutionsCannotApplyAndOpenVoteBlocksCompletion(){await using var f=await Setup();await f.Check();await f.Act("/votes",f.Open());var review=(await f.C.GetFromJsonAsync<CompletionReview>(f.Path+$"/completion-review?session={f.Session}",SecurityTestHost.Json))!;Assert.False(review.CanComplete);Assert.Contains(review.Checks,c=>c.Code=="Votes");await f.VoteAll(BallotChoice.Against);var r=await f.FinalizeVote();Assert.Equal(VoteOutcome.Rejected,r.Outcome);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/resolutions/{r.Id}/apply",new ApplyResolutionInput(f.V,Guid.NewGuid())));
  await using var g=await Setup();await g.Check();var input=g.Open() with{Options=new("Synthetic scope excludes all units",g.F.Data.Units.Select(u=>new ElectorateExclusion(u,"Synthetic material exclusion")).ToArray())};await g.Act("/votes",input);var undetermined=await g.FinalizeVote();Assert.Equal(VoteOutcome.Undetermined,undetermined.Outcome);Assert.Equal(HttpStatusCode.Conflict,await Status(g.C,g.Path+$"/resolutions/{undetermined.Id}/apply",new ApplyResolutionInput(g.V,Guid.NewGuid())));}
 [PostgresFact]public async Task FailedQuorumCanFinishOnlyWithAllAgendaExplicitlyDeferred(){await using var f=await Setup(false);await f.Check();await f.Act("/agenda-dispositions",new DispositionInput(f.V,f.F.D.Meeting.Agenda.Single().Id,AgendaDisposition.Deferred,"Synthetic no quorum, no decisions"));var review=(await f.C.GetFromJsonAsync<CompletionReview>(f.Path+$"/completion-review?session={f.Session}",SecurityTestHost.Json))!;Assert.True(review.CanComplete);await f.Act("/complete",new CompleteMeetingInput(f.V,Guid.NewGuid(),f.Session,review.Fingerprint,"Synthetic closure without deliberations"));Assert.NotNull(f.D.Completion);}
 [PostgresFact]public async Task M06ApprovalAndResolutionLinkRollbackTogetherWhenPersistenceFails(){await using var f=await Setup(target:MeetingReference.Budget);await f.Check();await f.Act("/votes",f.Open());var target=f.D.Votes.Single().Evidence.Target!;await f.VoteAll();var r=await f.FinalizeVote();await using var db=Db(f.F.Data.Base.Tenant);var constraint="CK_voting_test_"+Guid.NewGuid().ToString("N");await ExecuteDdl(db,$"ALTER TABLE \"ResolutionApplications\" ADD CONSTRAINT \"{constraint}\" CHECK (\"RelatedId\" <> '{target.Id}'::uuid)");var input=new ApplyResolutionInput(f.V,Guid.NewGuid());try{var status=await Status(f.C,f.Path+$"/resolutions/{r.Id}/apply",input);Assert.False(status is HttpStatusCode.OK or HttpStatusCode.Created);Assert.Equal(BudgetStatus.Proposed,(await db.Budgets.SingleAsync(b=>b.Id==target.Id)).Status);Assert.Equal(BudgetStatus.Approved,(await db.Budgets.SingleAsync(b=>b.Id==f.F.Data.Budget)).Status);Assert.False(await db.ResolutionApplications.AnyAsync(a=>a.RelatedId==target.Id));Assert.Equal(f.V,(await db.Meetings.SingleAsync(m=>m.Id==f.F.D.Meeting.Id)).Version);}finally{await ExecuteDdl(db,$"ALTER TABLE \"ResolutionApplications\" DROP CONSTRAINT \"{constraint}\"");}await f.Act($"/resolutions/{r.Id}/apply",input);Assert.Single(f.D.Applications);} [PostgresFact]public async Task SecondCallMustBuildItsOwnQuorumAndElectorate(){await using var f=await Setup();await f.Check();var first=f.D.Quorums.Last();await f.ExitAll();await f.F.Change($"/sessions/{f.Session}",new SessionTransition(f.V,SessionStatus.Ended));var second=f.F.D.Meeting.Sessions.Single(s=>s.Call==MeetingCall.Second);await f.F.Change($"/sessions/{second.Id}",new SessionTransition(f.V,SessionStatus.InProgress));async Task<VotingRuleDto> Template(string code){var t=VotingRuleTemplates.All().Single(t=>t.Code==code);var row=await Send<VotingRuleDto>(f.C,f.F.Base+"/voting-rules",new VotingRuleInput(code,"Synthetic second call criterion",t.Criteria,new(2026,1,1),null));return await Send<VotingRuleDto>(f.C,f.F.Base+$"/voting-rules/{row.Id}/activate",new RuleReviewInput("Synthetic explicit second-call review"));}var c=await Template("CC1136-CONST-2");var d=await Template("CC1136-ORD-2");await f.Act("/quorum",new QuorumInput(f.V,second.Id,c.Id,Options));Assert.Equal(QuorumOutcome.NotSatisfied,f.D.Quorums.Last().Outcome);Assert.Equal(HttpStatusCode.NotFound,await Status(f.C,f.Path+"/votes",new OpenVoteInput(f.V,Guid.NewGuid(),second.Id,f.F.D.Meeting.Agenda[0].Id,d.Id,first.Id,Options)));await f.F.Change("/attendances",new AttendanceInput(f.V,second.Id,f.F.Data.People[0],AttendanceType.InPerson,null,[f.F.Data.Units[0]],DateTimeOffset.UtcNow,null));await f.Act("/quorum",new QuorumInput(f.V,second.Id,c.Id,Options));Assert.Equal(QuorumOutcome.Satisfied,f.D.Quorums.Last().Outcome);Assert.Equal(1,f.D.Quorums.Last().Evaluation.Totals.Present);Assert.Equal(3,f.D.Quorums.First().Evaluation.Totals.Present);await f.Act("/votes",new OpenVoteInput(f.V,Guid.NewGuid(),second.Id,f.F.D.Meeting.Agenda[0].Id,d.Id,f.D.Quorums.Last().Id,Options));Assert.Single(f.D.Votes.Single().Evidence.Electorate.Rights.Where(r=>r.IsPresent));}
 [PostgresFact]public async Task SameOwnerOfTwoUnitsIsOneHeadWithCombinedValue(){var meeting=await MeetingTests.Setup();await using(var db=Db(meeting.Data.Base.Tenant)){var old=await db.OwnershipPeriods.SingleAsync(o=>o.PropertyUnitId==meeting.Data.Units[1]);old.End(new(2026,6,30));await db.SaveChangesAsync();}await Send<AssociationDto>(meeting.C,$"/api/condominiums/{meeting.Data.Base.Condo}/units/{meeting.Data.Units[1]}/associations",new AssociationInput(meeting.Data.People[0],UnitPersonRole.Owner,new(2026,7,1),null,1));await meeting.Convene();foreach(var n in meeting.D.Notices.ToArray()){await meeting.Change($"/notices/{n.Id}/status",new NoticeTransition(meeting.V,NoticeStatus.Ready,DateTimeOffset.UtcNow,null,null));await meeting.Change($"/notices/{n.Id}/status",new NoticeTransition(meeting.V,NoticeStatus.Sent,DateTimeOffset.UtcNow,"Synthetic declaration",null));}var session=meeting.D.Meeting.Sessions.First();await meeting.Change($"/sessions/{session.Id}",new SessionTransition(meeting.V,SessionStatus.InProgress));await meeting.Change("/attendances",new AttendanceInput(meeting.V,session.Id,meeting.Data.People[0],AttendanceType.InPerson,null,[meeting.Data.Units[0],meeting.Data.Units[1]],DateTimeOffset.UtcNow,null));await meeting.Change("/attendances",new AttendanceInput(meeting.V,session.Id,meeting.Data.People[2],AttendanceType.InPerson,null,[meeting.Data.Units[2]],DateTimeOffset.UtcNow,null));var c=await Rule(meeting,"C",VotingPurpose.Constitutive);var d=await Rule(meeting,"D",VotingPurpose.Deliberative);await using var f=new Fixture(meeting,c.Id,d.Id);await f.Check();Assert.Equal(2,f.D.Quorums.Single().Evaluation.Totals.Eligible);Assert.Equal(2,f.D.Quorums.Single().Evaluation.Totals.Present);await f.Act("/votes",f.Open());var head=f.D.Votes.Single().Evidence.Electorate.Rights.Single(r=>r.PrincipalId==meeting.Data.People[0]);Assert.Equal(2,head.PropertyUnitIds.Count);Assert.Equal(800,head.Millesimals);}}

